import { useEffect, useRef, useState } from 'react';
import { Link, Navigate, NavLink, Route, Routes, useLocation, useParams, useSearchParams } from 'react-router-dom';
import { catalog, courseById, courses, loadLessons, metaById } from './data/catalog';
import { conceptById, concepts } from './data/concepts';
import { Icon } from './components/Icon';
import { projectById, projects } from './data/projects';
import { mechanicById, mechanicCategoryNames, mechanics } from './data/mechanics';
import { genreById, genres } from './data/genres';
import { costNames, toolCategoryNames, tools } from './data/tools';
import { useProgress } from './state';
import { courseProgress, dueConcepts } from './progress';
import type { Course, Engine, Lesson, MechanicCategory, MediaSlot as MediaSlotData, Question, Tool } from './types';
import { Diagram, MediaSlot, PromptCard, QuestionCard, RenderBlock } from './components/Learning';
import { Demo } from './components/Demos';

const engineNames:Record<Engine,string>={browser:'Browser',godot:'Godot',unity:'Unity',unreal:'Unreal'};
const dimensionNames={'2d':'2D','3d':'3D','2d-3d':'2D & 3D'};
const foundationCourses=courses.filter(c=>c.track==='foundations');
const ladderCourses=courses.filter(c=>c.track==='ladder').sort((a,b)=>(a.level??9)-(b.level??9));
const classicCourses=courses.filter(c=>c.track==='classic');
const availableCourses=courses.filter(c=>c.availability==='available');
const lessonOrder=(course:Course)=>course.modules.flatMap(m=>m.lessonIds);

function Badge({children}:{children:React.ReactNode}){return <span className="tag">{children}</span>;}
function PageTitle({eyebrow,title,description}:{eyebrow:string;title:string;description:string}){useEffect(()=>{document.title=`${title} — ez gamedev`;},[title]);return <header className="page-title"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></header>;}
function ProgressBar({course}:{course:Course}){const {progress}=useProgress();const {done,total}=courseProgress(progress,course.id);const unit=course.track==='classic'?'lessons':'chapters';return <div className="course-progress"><progress value={done} max={Math.max(total,1)} aria-label={`${course.shortTitle} progress`}/><span>{done} / {total} {unit}</span></div>;}

/** Loads every foundations chapter, for pages that cross-link the libraries and chapters. */
function useFoundationLessons(){const [lessons,setLessons]=useState<Lesson[]|null>(null);useEffect(()=>{let active=true;Promise.all(foundationCourses.map(c=>loadLessons(c.id))).then(r=>{if(active)setLessons(r.flat());}).catch(()=>{if(active)setLessons([]);});return()=>{active=false;};},[]);return lessons;}

function Shell(){
 const {progress,warning,clearWarning,toggleTheme}=useProgress();const [menu,setMenu]=useState(false);const location=useLocation();const due=dueConcepts(progress).length;const page=useRef<HTMLElement>(null);
 useEffect(()=>{setMenu(false);window.scrollTo(0,0);page.current?.focus({preventScroll:true});},[location.pathname]);
 return <><a className="skip-link" href="#main-content" onClick={e=>{e.preventDefault();page.current?.focus();page.current?.scrollIntoView();}}>Skip to content</a>
 <header className="site-header"><Link to="/" className="brand" aria-label="ez gamedev home"><img className="brand-logo" src={`${import.meta.env.BASE_URL}assets/ez-gamedev-logo.png`} width="48" height="48" alt=""/><span>ez gamedev</span></Link>
  <button className="menu-button button ghost small" aria-expanded={menu} aria-controls="main-navigation" onClick={()=>setMenu(v=>!v)}>{menu?'Close':'Menu'}</button>
  <nav id="main-navigation" className={menu?'main-nav open':'main-nav'} aria-label="Main navigation">{[['/learn','Learn'],['/courses','Courses'],['/mechanics','Mechanics'],['/genres','Genres'],['/toolkit','Toolkit'],['/review','Review']].map(([path,title])=><NavLink key={path} to={path}>{title}{title==='Review'&&due>0&&<span className="nav-count">{due}</span>}</NavLink>)}</nav>
  <div className="header-tools"><button className="theme-button" aria-label={`Switch to ${progress.theme==='dark'?'light':'dark'} mode`} title="Toggle theme" onClick={e=>{const r=e.currentTarget.getBoundingClientRect();toggleTheme({x:r.left+r.width/2,y:r.top+r.height/2});}}><svg className="icon-sun" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2.5v2M12 19.5v2M4.6 4.6l1.4 1.4M18 18l1.4 1.4M2.5 12h2M19.5 12h2M4.6 19.4 6 18M18 6l1.4-1.4"/></svg><svg className="icon-moon" viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 14.2A8.5 8.5 0 1 1 9.8 3.5a6.6 6.6 0 0 0 10.7 10.7Z"/></svg></button><NavLink to="/progress" className="local-button"><span className="status-dot"/>Local progress</NavLink></div>
 </header>
 {warning&&<div className="storage-warning" role="status"><span>{warning}</span><button className="text-button" onClick={clearWarning}>Dismiss</button></div>}
 <main id="main-content" tabIndex={-1} ref={page}><Routes>
  <Route path="/" element={<Home/>}/><Route path="/learn" element={<Learn/>}/><Route path="/courses" element={<Courses/>}/><Route path="/courses/:courseId" element={<CoursePage/>}/><Route path="/courses/:courseId/lessons/:lessonId" element={<LessonPage/>}/>
  <Route path="/projects" element={<Projects/>}/><Route path="/projects/:projectId" element={<ProjectPage/>}/><Route path="/concepts" element={<Concepts/>}/><Route path="/concepts/:conceptId" element={<ConceptPage/>}/>
  <Route path="/mechanics" element={<Mechanics/>}/><Route path="/mechanics/:mechanicId" element={<MechanicPage/>}/><Route path="/genres" element={<Genres/>}/><Route path="/genres/:genreId" element={<GenrePage/>}/>
  <Route path="/toolkit" element={<Toolkit/>}/><Route path="/ecosystem" element={<Navigate to="/toolkit" replace/>}/><Route path="/media" element={<MediaChecklist/>}/>
  <Route path="/review" element={<Review/>}/><Route path="/progress" element={<ProgressPage/>}/><Route path="/labs" element={<Labs/>}/><Route path="*" element={<NotFound/>}/>
 </Routes></main>
 <footer className="site-footer"><span>Easy path first. Your own skills whenever you want them.</span><div><Link to="/concepts">Concepts</Link><Link to="/projects">Projects</Link><Link to="/labs">Interactive labs</Link><Link to="/toolkit">Toolkit</Link></div></footer></>;
}
export function App(){return <Shell/>;}

function HomeSketch(){return <figure className="home-sketch"><img src={`${import.meta.env.BASE_URL}assets/game-world.png`} width="1536" height="1024" alt="An explorer assembling a small world of terracotta platforms, an olive tree, and a tower."/><figcaption>A small world. A few rules. Something to play.</figcaption></figure>;}
function Home(){
 const {progress}=useProgress();const resume=progress.resume&&metaById[progress.resume];
 return <div className="page home">
  <section className="home-intro"><div><span className="eyebrow"><span className="status-dot"/> Game development for vibe coders</span><h1>Make games with AI.<br/><span>Know what to ask for.</span></h1>
   <p>Learn what games are made of: genres, mechanics, art, sound, levels, cameras, and engines. Then direct coding agents, MCP servers, and asset generators to build them, with a do-it-yourself path whenever you want more control.</p>
   <div className="button-row"><Link className="button" to={resume?`/courses/${resume.courseId}/lessons/${resume.id}`:'/courses/f-game'}>{resume?'Continue learning':'Start with What Makes a Game'}<Icon name="arrow-right"/></Link><Link className="button ghost" to="/toolkit">Browse the toolkit</Link></div>
   <p className="home-note">Story-driven chapters. Real games as examples. No programming required.</p></div><HomeSketch/></section>
  <section className="path-section"><div className="section-heading"><h2>Start here: the foundations</h2><span className="tiny-label">Four story courses</span></div><div className="course-grid">{foundationCourses.map(c=><CourseCard key={c.id} course={c}/>)}</div></section>
  <section className="section-space"><div className="section-heading"><h2>Then build: the hands-on ladder</h2><Link className="text-link" to="/courses">All courses <Icon name="arrow-right"/></Link></div><p className="section-intro">Every hands-on course follows the same pattern: the easy AI path first, free assets second, and a do-it-yourself option for when you want more. These courses are outlined and coming next.</p><div className="ladder-strip">{ladderCourses.filter(c=>c.level).map(c=><Link key={c.id} to={`/courses/${c.id}`}><span className="level-badge">Lv {c.level}</span><span><strong>{c.title}</strong><small>{engineNames[c.engine!]} · {dimensionNames[c.dimension!]}</small></span></Link>)}</div></section>
  <section className="learning-loop-section"><div><span className="eyebrow">Easy path first, options second</span><h2>Every part of a game,<br/>three ways to make it.</h2><p>For code, art, sound, and levels, each chapter shows what AI can do for you, where to find free assets, and which tools to learn if you want to make it yourself.</p><Link className="text-link" to="/toolkit">See every tool <Icon name="arrow-right"/></Link></div><div className="three-paths"><div><span className="eyebrow">1 · AI crew</span><p>Coding agents, MCP servers, and image, 3D, and audio generators.</p></div><div><span className="eyebrow">2 · Free assets</span><p>Kenney, Poly Haven, Quaternius, OpenGameArt, Freesound, and more.</p></div><div><span className="eyebrow">3 · Do it yourself</span><p>Blender, Aseprite, Krita, Tiled, Audacity, and the engines themselves.</p></div></div></section>
  <section className="home-projects"><div className="section-heading"><h2>Libraries to keep close</h2></div><div className="project-strip">
   <Link to="/mechanics"><span className="project-number">{mechanics.length}</span><h3>Game mechanics</h3><p>From coyote time to shrinking zones, each with real games that use it.</p><span className="tiny-label">Mechanics library <Icon name="arrow-right"/></span></Link>
   <Link to="/genres"><span className="project-number">{genres.length}</span><h3>Genres</h3><p>Origins, signature mechanics, landmark games, and success stories.</p><span className="tiny-label">Genre library <Icon name="arrow-right"/></span></Link>
   <Link to="/labs"><span className="project-number">14</span><h3>Interactive labs</h3><p>Play with loops, cameras, parallax, isometric views, collisions, and more.</p><span className="tiny-label">Labs <Icon name="arrow-right"/></span></Link>
  </div></section>
 </div>;
}

function CourseCard({course}:{course:Course}){
 const chapters=catalog.filter(l=>l.courseId===course.id).length;
 const badge=course.level?`Lv ${course.level}`:course.track==='foundations'?course.number:course.track==='classic'?'Classic':'Later';
 return <Link className={`course-card ${course.availability}`} to={`/courses/${course.id}`}>
  <div className="course-card-top"><span className="level-badge">{badge}</span>{course.engine&&<span className="tag">{engineNames[course.engine]} · {dimensionNames[course.dimension!]}</span>}{course.availability==='planned'&&<span className="tag soon">coming soon</span>}</div>
  <h3>{course.title}</h3><p>{course.subtitle}</p>{course.builds&&<p className="fine">You’ll build: {course.builds}</p>}
  <div className="course-card-foot">{course.availability==='available'?<ProgressBar course={course}/>:<span className="fine">{chapters} chapters outlined</span>}</div>
 </Link>;
}

function Learn(){
 const {progress}=useProgress();const resume=progress.resume&&metaById[progress.resume];const current=progress.currentProject&&projectById[progress.currentProject];
 return <div className="page"><PageTitle eyebrow="Your workbench" title="A little further, every time." description="Pick up where you left off, or choose the next part of game-making you want to understand."/>
  <div className="dashboard-grid"><section className="resume-panel"><span className="eyebrow">{resume?'Continue learning':'Your first chapter'}</span><h2>{resume?resume.title:'What is a game?'}</h2><p>{resume?resume.outcome:'Find the five ingredients every game shares, from chalk hopscotch to phone games.'}</p><Link className="button" to={resume?`/courses/${resume.courseId}/lessons/${resume.id}`:'/courses/f-game/lessons/fg-what-is-a-game'}>{resume?'Resume':'Begin chapter'} <Icon name="arrow-right"/></Link></section>
  <section className="review-summary"><span className="eyebrow">Keep the ideas close</span><h2>{dueConcepts(progress).length} concepts to revisit</h2><p>Completed chapters add concepts to your review queue. Missed questions return sooner.</p><Link className="text-link" to="/review">Open review <Icon name="arrow-right"/></Link></section></div>
  <section className="section-space"><div className="section-heading"><h2>Your courses</h2><Link className="text-link" to="/courses">Browse all courses <Icon name="arrow-right"/></Link></div>{availableCourses.map(c=><Link key={c.id} className="course-list-row" to={`/courses/${c.id}`}><span className="chapter-marker">{c.number}</span><div><h3>{c.title}</h3><p>{c.subtitle}</p><ProgressBar course={c}/></div><Icon name="arrow-right"/></Link>)}</section>
  {current&&<section className="section-space"><span className="eyebrow">Current project</span><h2>{current.title}</h2><p>{current.description}</p><Link className="text-link" to={`/projects/${current.id}`}>Open project <Icon name="arrow-right"/></Link></section>}
 </div>;
}

function Courses(){
 const [engine,setEngine]=useState<'all'|Engine>('all');const [dim,setDim]=useState<'all'|'2d'|'3d'>('all');
 const ladder=ladderCourses.filter(c=>(engine==='all'||c.engine===engine)&&(dim==='all'||c.dimension===dim||c.dimension==='2d-3d'));
 return <div className="page"><PageTitle eyebrow="The curriculum" title="Choose your path." description="Start with the story-driven foundations, then climb the hands-on ladder from Level 1 to Level 5. Every course is open to explore."/>
  <section><div className="section-heading"><h2>Start here: foundations</h2><span className="tiny-label">For everyone</span></div><div className="course-grid">{foundationCourses.map(c=><CourseCard key={c.id} course={c}/>)}</div></section>
  <section className="section-space"><div className="section-heading"><h2>The hands-on ladder</h2><span className="tiny-label">Levels 1–5</span></div><p className="section-intro">Build real games with AI first, free assets second, and do-it-yourself options third. These courses are outlined; the first levels are being written next.</p>
   <div className="filter-row" aria-label="Filter by engine">{(['all','browser','godot','unity','unreal'] as const).map(id=><button key={id} className={engine===id?'active':''} aria-pressed={engine===id} onClick={()=>setEngine(id)}>{id==='all'?'All engines':engineNames[id]}</button>)}</div>
   <div className="filter-row" aria-label="Filter by dimension">{(['all','2d','3d'] as const).map(id=><button key={id} className={dim===id?'active':''} aria-pressed={dim===id} onClick={()=>setDim(id)}>{id==='all'?'2D and 3D':dimensionNames[id]}</button>)}</div>
   <div className="course-grid">{ladder.map(c=><CourseCard key={c.id} course={c}/>)}</div>{!ladder.length&&<p className="fine">No courses match these filters yet.</p>}</section>
  <section className="section-space"><div className="section-heading"><h2>Classic, code-first</h2></div><div className="course-grid">{classicCourses.map(c=><CourseCard key={c.id} course={c}/>)}</div></section>
 </div>;
}

function Roadmap({course,compact=false,current,hideBridge=false}:{course:Course;compact?:boolean;current?:string;hideBridge?:boolean}){const {progress}=useProgress();return <div className={`roadmap ${compact?'compact':''}`}>{course.modules.filter(m=>!(hideBridge&&m.optional)).map((m,i)=><section className="roadmap-module" key={m.id}><div className="module-heading"><span className="module-index">{String(i+1).padStart(2,'0')}</span><div><h3>{m.title}{m.optional&&<span className="tag">optional</span>}</h3>{!compact&&<p>{m.description}</p>}</div></div><ol>{m.lessonIds.map(id=>{const meta=metaById[id];const done=progress.completed.includes(id);return <li key={id}><Link to={`/courses/${course.id}/lessons/${id}`} className={`${current===id?'current ':''}${done?'done':''}`} aria-current={current===id?'page':undefined}><span className="checkpoint" aria-label={done?'Completed':meta.status==='preview'?'Preview':'Not completed'}>{done?<Icon name="check"/>:meta.status==='preview'?'·':''}</span><span>{meta.title}</span>{!compact&&<small>{meta.status==='preview'?'outline':`${meta.minutes} min`}</small>}</Link></li>;})}</ol></section>)}</div>;}

/** The foundations course map: chapters as numbered stops along a path, grouped by part. */
function JourneyMap({course}:{course:Course}){
 const {progress}=useProgress();const order=lessonOrder(course);
 return <div className="journey">{course.modules.map(m=><section key={m.id} className="journey-part"><h3>{m.title}</h3><p className="fine">{m.description}</p><ol>{m.lessonIds.map(id=>{const done=progress.completed.includes(id);return <li key={id}><Link to={`/courses/${course.id}/lessons/${id}`} className={done?'done':''}><span className="journey-stop" aria-label={done?'Completed':'Not completed'}>{done?<Icon name="check"/>:order.indexOf(id)+1}</span><span>{metaById[id].title}</span></Link></li>;})}</ol></section>)}</div>;
}
function CompletionCard({course}:{course:Course}){
 const next=foundationCourses.find(c=>c.id!==course.id);
 return <section className="completion-card" aria-live="polite"><span className="completion-star" aria-hidden="true"><Icon name="star"/></span><div><span className="eyebrow">Course complete</span><h2>You finished {course.title}.</h2><p>Every chapter is checked off, and its ideas are in your review queue. Keep them fresh, then carry on.</p><div className="button-row"><Link className="button small" to="/review">Open review</Link>{next&&<Link className="button ghost small" to={`/courses/${next.id}`}>Try {next.title} <Icon name="arrow-right"/></Link>}<Link className="text-link" to="/courses">All courses <Icon name="arrow-right"/></Link></div></div></section>;
}

function CoursePage(){
 const {courseId}=useParams();const course=courseById[courseId||''];const {progress}=useProgress();const [fast,setFast]=useState(false);
 if(!course)return <NotFound/>;
 const published=catalog.filter(l=>l.courseId===course.id&&l.status==='complete');const all=lessonOrder(course);
 const {done,total}=courseProgress(progress,course.id);const first=fast&&course.id==='godot'?'g-editor':(published[0]?.id??all[0]);
 const eyebrow=course.track==='foundations'?`Foundations ${course.number} · For everyone`:course.track==='ladder'?`${course.level?`Level ${course.level}`:'Planned'} · ${engineNames[course.engine!]} ${dimensionNames[course.dimension!]}`:`Classic course · ${course.difficulty}`;
 return <div className="page"><Link className="breadcrumb" to="/courses"><Icon name="arrow-left"/>All courses</Link><PageTitle eyebrow={eyebrow} title={course.title} description={course.description}/>
  {course.availability==='planned'&&<div className="preview-notice"><span className="tag">Coming soon</span><p>This course is outlined. Its chapters show what it will cover; they will be written after the foundations. {course.builds&&<>You’ll build: <strong>{course.builds}</strong>.</>}</p></div>}
  {course.availability==='available'&&total>0&&done===total&&<CompletionCard course={course}/>}
  <div className="course-start"><div>{course.availability==='available'?<ProgressBar course={course}/>:<p className="fine">{all.length} chapters outlined</p>}<p className="fine">{course.track==='foundations'?`${all.length} story chapters · about ${all.length*12} minutes · no programming required`:course.track==='classic'?`${published.length} complete lessons · Godot 4.7.2 · 2D + 3D`:'Easy AI path first · free assets second · do it yourself third'}</p></div><Link className="button" to={`/courses/${course.id}/lessons/${first}`}>{done>0&&done<total?'Continue course':'Start course'} <Icon name="arrow-right"/></Link></div>
  <div className="course-information"><div><h3>Who this is for</h3><p>{course.audience}</p><h3>Bring with you</h3><ul>{course.prerequisites.map(p=><li key={p}>{p}</li>)}</ul></div><div><h3>You don’t need</h3><ul>{course.notRequired.map(p=><li key={p}>{p}</li>)}</ul><h3>You’ll leave able to</h3><ul>{course.outcomes.map(p=><li key={p}>{p}</li>)}</ul></div></div>
  {course.selfCheck.length>0&&<details className="disclosure prerequisite-check"><summary>Take a quick prerequisite self-check <span className="tag">advisory</span></summary><p>These questions help you choose a starting point. You can always continue; unfamiliar concepts are linked below.</p>{course.selfCheck.map(q=><QuestionCard key={q.id} question={q}/>)}<Link className="text-link" to="/courses/godot/lessons/g-variables">Review the recommended starting point <Icon name="arrow-right"/></Link></details>}
  <section className="section-space"><div className="section-heading"><h2>{course.track==='foundations'?'Your journey':'Your course map'}</h2>{course.id==='godot'&&<label className="check-label"><input type="checkbox" checked={fast} onChange={e=>setFast(e.target.checked)}/> Programmer fast track</label>}</div>{fast&&<p className="fine">The optional programming bridge is hidden. You can return to it whenever you need it.</p>}{course.track==='foundations'?<JourneyMap course={course}/>:<Roadmap course={course} hideBridge={fast}/>}</section>
  {course.projectIds.length>0&&<section className="section-space"><h2>Build alongside the lessons</h2><div className="project-strip">{course.projectIds.map(id=><ProjectLink key={id} id={id}/>)}</div></section>}
 </div>;
}

function useLessons(id:string){const [state,setState]=useState<{id:string;lessons:Lesson[];error:boolean}>({id:'',lessons:[],error:false});useEffect(()=>{let active=true;loadLessons(id).then(lessons=>{if(active)setState({id,lessons,error:false});}).catch(()=>{if(active)setState({id,lessons:[],error:true});});return()=>{active=false;};},[id]);return state.id===id?state:{id,lessons:[],error:false};}

function LessonPage(){
 const {courseId='',lessonId=''}=useParams();const course=courseById[courseId];const {lessons,error}=useLessons(courseId);const lesson=lessons.find(l=>l.id===lessonId);const {progress,complete,setResume}=useProgress();
 useEffect(()=>{if(metaById[lessonId]?.courseId===courseId)setResume(lessonId);},[lessonId,courseId]);
 useEffect(()=>{if(lesson)document.title=`${lesson.title} — ez gamedev`;},[lesson]);
 if(!course||metaById[lessonId]?.courseId!==courseId)return <NotFound/>;
 if(error)return <div className="page empty-state"><h1>Couldn’t load this chapter.</h1><p>Reload the page to try again.</p><button className="button" onClick={()=>window.location.reload()}>Reload</button></div>;
 if(!lesson)return <div className="page loading">Loading your chapter…</div>;
 const order=lessonOrder(course);const position=order.indexOf(lesson.id);
 const nextId=order.slice(position+1).find(id=>metaById[id].status==='complete'||course.availability==='planned');const next=nextId?metaById[nextId]:undefined;
 const module=course.modules.find(m=>m.id===lesson.moduleId)!;const done=progress.completed.includes(lesson.id);const story=course.track==='foundations';
 const courseDone=course.availability==='available'&&order.every(id=>progress.completed.includes(id));
 return <div className="lesson-layout"><aside className="lesson-sidebar"><Link className="breadcrumb" to={`/courses/${course.id}`}><Icon name="arrow-left"/>{course.shortTitle}</Link><ProgressBar course={course}/><div className="sidebar-scroll"><Roadmap course={course} compact current={lesson.id}/></div></aside>
 <article className="lesson-content" key={lesson.id}>
  <div className="lesson-breadcrumb"><Link to={`/courses/${course.id}`}>{course.shortTitle}</Link><span>/</span><span>{module.title}</span></div>
  <header className="lesson-header"><div className="button-row"><Badge>{lesson.difficulty}</Badge><span className="fine">Chapter {position+1} of {order.length} · {story?`~${lesson.minutes} min`:`${lesson.minutes} min · self-paced`}</span>{done&&<span className="completion-stamp"><Icon name="check"/> completed</span>}</div><h1>{lesson.title}</h1><p className="lesson-goal">{lesson.outcome}</p>
   {story&&<nav className="chapter-dots" aria-label="Chapters in this course">{order.map((id,i)=><Link key={id} to={`/courses/${course.id}/lessons/${id}`} className={`${id===lesson.id?'current ':''}${progress.completed.includes(id)?'done':''}`} aria-label={`Chapter ${i+1}: ${metaById[id].title}${progress.completed.includes(id)?' (completed)':''}`} aria-current={id===lesson.id?'page':undefined}/>)}</nav>}
   {lesson.prerequisites.length>0&&<p className="fine builds-on">Builds on: {lesson.prerequisites.map((id,i)=><span key={id}>{i>0&&', '}<Link to={`/courses/${metaById[id].courseId}/lessons/${id}`}>{metaById[id].title}</Link></span>)}</p>}
  </header>
  <details className="mobile-course-map disclosure"><summary>Open course map</summary><Roadmap course={course} compact current={lesson.id}/></details>
  {lesson.status==='preview'&&<div className="preview-notice"><span className="tag">Coming soon</span><p>This chapter is outlined but not written yet, so it cannot count toward completion.</p></div>}
  {lesson.blocks.map((block,i)=><RenderBlock key={i} block={block}/>)}
  {lesson.summary.length>0&&<section className="lesson-summary"><span className="eyebrow">Keep these ideas</span><h2>Before you move on</h2><ul>{lesson.summary.map(p=><li key={p}>{p}</li>)}</ul></section>}
  {(lesson.mechanics?.length||lesson.genres?.length)?<section className="concept-links"><h3>Explore in the libraries</h3><div className="tag-links">{lesson.mechanics?.map(id=><Link key={id} to={`/mechanics/${id}`}>{mechanicById[id].name} <Icon name="arrow-right"/></Link>)}{lesson.genres?.map(id=><Link key={id} to={`/genres/${id}`}>{genreById[id].name} <Icon name="arrow-right"/></Link>)}</div></section>:null}
  <section className="concept-links"><h3>Connected concepts</h3><div className="tag-links">{lesson.concepts.map(id=><Link key={id} to={`/concepts/${id}`}>{conceptById[id].title} <Icon name="arrow-right"/></Link>)}</div></section>
  {course.id==='godot'&&<p className="fine source-note">Examples target Godot 4.7.2. <a href={lesson.source||'https://docs.godotengine.org/en/stable/'} target="_blank" rel="noreferrer">Engine reference <Icon name="external"/></a></p>}
  <div className="lesson-bottom">
   {lesson.status==='complete'&&<><button className={`button ${done?'ghost':''}`} onClick={()=>complete(lesson.id)} disabled={done}>{done?<><Icon name="check"/> Checkpoint complete</>:'Mark lesson complete'}</button><p className="fine">Try the activity and the quick check first. Concepts return for review tomorrow.</p></>}
   {lesson.teaser&&<p className="teaser">{lesson.teaser}</p>}
   {next&&<Link className="next-lesson" to={`/courses/${course.id}/lessons/${next.id}`}><span className="eyebrow">Next chapter</span><strong>{next.title} <Icon name="arrow-right"/></strong><p>{next.outcome}</p></Link>}
   {!next&&lesson.status==='complete'&&(course.projectIds.length?<Link className="text-link" to={`/projects/${course.projectIds.at(-1)}`}>Put the course to work <Icon name="arrow-right"/></Link>:<Link className="text-link" to={`/courses/${course.id}`}>{courseDone?'See your finished journey':'Back to the course map'} <Icon name="arrow-right"/></Link>)}
  </div>
 </article></div>;
}

function ProjectLink({id}:{id:string}){const p=projectById[id];return <Link to={`/projects/${id}`}><span className="eyebrow">{courseById[p.courseId].shortTitle}</span><h3>{p.title}</h3><p>{p.description}</p><span className="tiny-label">{p.difficulty} <Icon name="arrow-right"/></span></Link>;}
function Projects(){return <div className="page"><PageTitle eyebrow="The build bench" title="Learn it by making it." description="Each project is a sequence of observable milestones. These belong to the classic Godot course; the hands-on ladder courses will add their own."/><div className="project-grid">{projects.map(p=><ProjectLink key={p.id} id={p.id}/>)}</div></div>;}
function ProjectPage(){const {projectId=''}=useParams();const project=projectById[projectId];const {progress,milestone,setProject}=useProgress();const [hints,setHints]=useState(0);if(!project)return <NotFound/>;const done=project.milestones.filter(m=>progress.milestones.includes(m.id)).length;return <div className="page project-detail"><Link className="breadcrumb" to="/projects"><Icon name="arrow-left"/>All projects</Link><PageTitle eyebrow={`Project · ${project.difficulty}`} title={project.title} description={project.description}/><div className="course-start"><div><progress value={done} max={project.milestones.length} aria-label="Project progress"/><p className="fine">{done} / {project.milestones.length} milestones complete</p></div><button className="button" disabled={progress.currentProject===project.id} onClick={()=>setProject(project.id)}>{progress.currentProject===project.id?<><Icon name="check"/> Current project</>:'Set as current project'}</button></div><section className="section-space"><h2>The finished behavior</h2><p>{project.outcome}</p><div className="tag-links">{project.concepts.map(id=><Link key={id} to={`/concepts/${id}`}>{conceptById[id].title}</Link>)}</div></section><section className="section-space"><h2>Recommended build order</h2><div className="project-milestones">{project.milestones.map((m,i)=><section key={m.id} className={progress.milestones.includes(m.id)?'milestone-complete':''}><label className="milestone-title"><input type="checkbox" checked={progress.milestones.includes(m.id)} onChange={()=>milestone(m.id)}/><span className="tiny-label">{String(i+1).padStart(2,'0')}</span><h3>{m.title}</h3></label><p>{m.task}</p><ul>{m.checks.map(c=><li key={c}>{c}</li>)}</ul><div className="milestone-lessons">{m.lessonIds.map(id=><Link key={id} to={`/courses/${metaById[id].courseId}/lessons/${id}`}>{metaById[id].title} <Icon name="arrow-right"/></Link>)}</div></section>)}</div></section><section className="section-space"><h2>A nudge, when you need it</h2>{project.hints.slice(0,hints).map((hint,i)=><p key={hint}><span className="tiny-label">HINT {i+1}</span> {hint}</p>)}{hints<project.hints.length&&<button className="button ghost small" onClick={()=>setHints(v=>v+1)}>Reveal next hint</button>}</section><PromptCard title="Work on one milestone" text={project.prompt} why="Replace the placeholders with your real files, current scene tree, and one observable goal."/><div className="course-information"><div><h3>Common mistakes</h3><ul>{project.mistakes.map(m=><li key={m}>{m}</li>)}</ul></div><div><h3>Optional extensions</h3><ul>{project.enhancements.map(m=><li key={m}>{m}</li>)}</ul></div></div>{project.courseId==='godot'&&project.id!=='independent-game'&&<section className="reference-download"><span className="eyebrow">After your own attempt</span><details className="disclosure"><summary>Compare with a small runnable reference</summary><p>This compact reference uses placeholder geometry and a reduced feature set to demonstrate the core loop. It is a comparison aid; the milestones above take your project further.</p><a className="button ghost small" href={`${import.meta.env.BASE_URL}downloads/${project.id}.zip`} download>Download Godot reference project</a></details></section>}</div>;}

function SearchField({label,placeholder,value,onChange,count,unit}:{label:string;placeholder:string;value:string;onChange:(v:string)=>void;count:number;unit:string}){return <label className="search-field"><Icon name="search" className="search-icon"/><input aria-label={label} placeholder={placeholder} value={value} onChange={e=>onChange(e.target.value)}/><span className="fine">{count} {unit}</span></label>;}
function Concepts(){const [params,setParams]=useSearchParams();const query=params.get('q')||'';const matches=concepts.filter(c=>`${c.title} ${c.definition} ${c.usage}`.toLowerCase().includes(query.toLowerCase().trim()));return <div className="page"><PageTitle eyebrow="The concept library" title="Keep the mental models handy." description="A clear definition, a useful picture, and a connection to something you can build."/><SearchField label="Search concepts" placeholder="Search concepts, e.g. shader or collision" value={query} onChange={v=>setParams(v?{q:v}:{},{replace:true})} count={matches.length} unit="concepts"/><div className="concept-list">{matches.map(c=><Link to={`/concepts/${c.id}`} key={c.id}><h2>{c.title}</h2><p>{c.definition}</p><Icon name="arrow-right"/></Link>)}</div>{!matches.length&&<div className="empty-state"><h2>No matching concepts.</h2><p>Try a broader term.</p><button className="button ghost small" onClick={()=>setParams({})}>Clear search</button></div>}</div>;}
function ConceptPage(){const {conceptId=''}=useParams();const c=conceptById[conceptId];if(!c)return <NotFound/>;const lessons=catalog.filter(l=>l.concepts.includes(c.id));return <div className="page narrow-page"><Link className="breadcrumb" to="/concepts"><Icon name="arrow-left"/>Concept library</Link><PageTitle eyebrow="Mental model" title={c.title} description={c.definition}/><section className="prose-section"><h2>Why it exists</h2><p>{c.why}</p></section><Diagram title="THE MODEL" nodes={c.model}/>{c.demo&&<Demo kind={c.demo}/>}<section className="prose-section"><h2>A concrete example</h2><p>{c.example}</p><h2>Where you’ll use it</h2><p>{c.usage}</p></section><section className="section-space"><h3>Connect it to</h3><div className="tag-links">{c.related.map(id=><Link key={id} to={`/concepts/${id}`}>{conceptById[id].title} <Icon name="arrow-right"/></Link>)}</div></section><section className="section-space"><h3>Learn it in context</h3><div className="related-lessons">{lessons.map(l=><Link key={l.id} to={`/courses/${l.courseId}/lessons/${l.id}`}><span>{l.title}</span><small>{courseById[l.courseId].shortTitle}{l.status==='preview'?' · coming soon':''} <Icon name="arrow-right"/></small></Link>)}</div></section></div>;}

function RelatedChapters({match}:{match:(l:Lesson)=>boolean}){const lessons=useFoundationLessons();if(lessons===null)return <p className="loading">Finding chapters…</p>;const found=lessons.filter(match);if(!found.length)return <p className="fine">Not featured in a chapter yet.</p>;return <div className="related-lessons">{found.map(l=><Link key={l.id} to={`/courses/${l.courseId}/lessons/${l.id}`}><span>{l.title}</span><small>{courseById[l.courseId].shortTitle} <Icon name="arrow-right"/></small></Link>)}</div>;}
function Mechanics(){
 const [params,setParams]=useSearchParams();const query=(params.get('q')||'').toLowerCase().trim();const category=(params.get('category')||'all') as 'all'|MechanicCategory;
 const set=(next:Record<string,string>)=>{const merged={q:params.get('q')||'',category:params.get('category')||'',...next};setParams(Object.fromEntries(Object.entries(merged).filter(([,v])=>v&&v!=='all')),{replace:true});};
 const matches=mechanics.filter(m=>(category==='all'||m.category===category)&&`${m.name} ${m.description} ${m.examples.join(' ')}`.toLowerCase().includes(query));
 const groups=(Object.keys(mechanicCategoryNames) as MechanicCategory[]).map(cat=>[cat,matches.filter(m=>m.category===cat)] as const).filter(([,list])=>list.length);
 return <div className="page"><PageTitle eyebrow="The mechanics library" title="The verbs of play." description={`${mechanics.length} mechanics in ${Object.keys(mechanicCategoryNames).length} families, each explained in plain words with real games that use it. Borrow freely: every mechanic here has been refined by many games before yours.`}/>
  <SearchField label="Search mechanics" placeholder="Search, e.g. dash, stealth, or Celeste" value={params.get('q')||''} onChange={v=>set({q:v})} count={matches.length} unit="mechanics"/>
  <div className="filter-row" aria-label="Filter by category"><button className={category==='all'?'active':''} aria-pressed={category==='all'} onClick={()=>set({category:'all'})}>All</button>{(Object.entries(mechanicCategoryNames) as [MechanicCategory,string][]).map(([id,name])=><button key={id} className={category===id?'active':''} aria-pressed={category===id} onClick={()=>set({category:id})}>{name}</button>)}</div>
  {groups.map(([cat,list])=><section key={cat} className="library-group"><h2>{mechanicCategoryNames[cat]}</h2><div className="library-grid">{list.map(m=><Link key={m.id} to={`/mechanics/${m.id}`}><h3>{m.name}</h3><p>{m.description}</p><span className="fine">{m.examples[0]}</span></Link>)}</div></section>)}
  {!matches.length&&<div className="empty-state"><h2>No matching mechanics.</h2><button className="button ghost small" onClick={()=>setParams({})}>Clear filters</button></div>}
 </div>;
}
function MechanicPage(){
 const {mechanicId=''}=useParams();const m=mechanicById[mechanicId];if(!m)return <NotFound/>;const siblings=mechanics.filter(x=>x.category===m.category&&x.id!==m.id).slice(0,8);
 return <div className="page narrow-page"><Link className="breadcrumb" to="/mechanics"><Icon name="arrow-left"/>Mechanics library</Link><PageTitle eyebrow={`Mechanic · ${mechanicCategoryNames[m.category]}`} title={m.name} description={m.description}/>
  <section className="prose-section"><h2>Why designers use it</h2><p>{m.why}</p></section>
  <section className="section-space"><h3>Seen in</h3><ul>{m.examples.map(e=><li key={e}>{e}</li>)}</ul></section>
  <section className="section-space"><h3>Genres that use it</h3><div className="tag-links">{m.genres.map(id=><Link key={id} to={`/genres/${id}`}>{genreById[id].name} <Icon name="arrow-right"/></Link>)}</div></section>
  <section className="section-space"><h3>In the foundations chapters</h3><RelatedChapters match={l=>!!l.mechanics?.includes(m.id)}/></section>
  {siblings.length>0&&<section className="section-space"><h3>More {mechanicCategoryNames[m.category].toLowerCase()} mechanics</h3><div className="tag-links">{siblings.map(x=><Link key={x.id} to={`/mechanics/${x.id}`}>{x.name}</Link>)}</div></section>}
  <PromptCard title="Ask your agent to build it" text={`Add the “${m.name}” mechanic to my game: ${m.description} My game is [one-sentence description] built with [engine]. Put every tuning number in one settings block, and tell me three ways to test it, including one edge case.`} why="Name the mechanic and describe it precisely; agents build clear, testable behaviors far better than vague ones." eyebrow="AI prompt"/>
 </div>;
}
function Genres(){
 const [params,setParams]=useSearchParams();const query=(params.get('q')||'').toLowerCase().trim();const matches=genres.filter(g=>`${g.name} ${g.summary} ${g.landmarks.join(' ')}`.toLowerCase().includes(query));
 return <div className="page"><PageTitle eyebrow="The genre library" title="Families of play." description={`${genres.length} genres and subgenres: where each came from, the mechanics that define it, landmark games, and a success story.`}/>
  <SearchField label="Search genres" placeholder="Search, e.g. roguelite or farming" value={params.get('q')||''} onChange={v=>setParams(v?{q:v}:{},{replace:true})} count={matches.length} unit="genres"/>
  <div className="library-grid">{matches.map(g=><Link key={g.id} to={`/genres/${g.id}`}>{g.parent&&<span className="eyebrow">{genreById[g.parent].name} family</span>}<h3>{g.name}</h3><p>{g.summary}</p><span className="fine">{g.landmarks[0]}</span></Link>)}</div>
  {!matches.length&&<div className="empty-state"><h2>No matching genres.</h2><button className="button ghost small" onClick={()=>setParams({})}>Clear search</button></div>}
 </div>;
}
function GenrePage(){
 const {genreId=''}=useParams();const g=genreById[genreId];if(!g)return <NotFound/>;const children=genres.filter(x=>x.parent===g.id);const usedBy=mechanics.filter(m=>m.genres.includes(g.id)&&!g.mechanics.includes(m.id));
 return <div className="page narrow-page"><Link className="breadcrumb" to="/genres"><Icon name="arrow-left"/>Genre library</Link><PageTitle eyebrow={g.parent?`Genre · Part of ${genreById[g.parent].name}`:'Genre'} title={g.name} description={g.summary}/>
  <section className="prose-section"><h2>Where it came from</h2><p>{g.origin}</p><h2>A success story</h2><p>{g.story}</p></section>
  <section className="section-space"><h3>Landmark games</h3><ul>{g.landmarks.map(l=><li key={l}>{l}</li>)}</ul></section>
  <section className="section-space"><h3>Signature mechanics</h3><div className="tag-links">{g.mechanics.map(id=><Link key={id} to={`/mechanics/${id}`}>{mechanicById[id].name} <Icon name="arrow-right"/></Link>)}</div>{usedBy.length>0&&<><h3 className="section-space">Also common</h3><div className="tag-links">{usedBy.map(m=><Link key={m.id} to={`/mechanics/${m.id}`}>{m.name}</Link>)}</div></>}</section>
  {children.length>0&&<section className="section-space"><h3>Subgenres</h3><div className="tag-links">{children.map(c=><Link key={c.id} to={`/genres/${c.id}`}>{c.name} <Icon name="arrow-right"/></Link>)}</div></section>}
  <section className="section-space"><h3>In the foundations chapters</h3><RelatedChapters match={l=>!!l.genres?.includes(g.id)}/></section>
 </div>;
}
const pathNames:Record<Tool['path'],string>={ai:'AI crew',library:'Free asset libraries',manual:'Do it yourself'};
function Toolkit(){
 const [path,setPath]=useState<'all'|Tool['path']>('all');const shown=tools.filter(t=>path==='all'||t.path===path);
 const categories=(Object.keys(toolCategoryNames) as Tool['category'][]).filter(c=>shown.some(t=>t.category===c));
 return <div className="page"><PageTitle eyebrow="The toolkit" title="Easy path first. Options second." description="Engines, coding agents, MCP servers, AI generators, free asset libraries, and do-it-yourself tools. Free options come first; paid tools are tagged. Prices and plans change, so check each tool’s site and license before you rely on it."/>
  <div className="filter-row" aria-label="Filter by path"><button className={path==='all'?'active':''} aria-pressed={path==='all'} onClick={()=>setPath('all')}>Everything</button>{(Object.entries(pathNames) as [Tool['path'],string][]).map(([id,name])=><button key={id} className={path===id?'active':''} aria-pressed={path===id} onClick={()=>setPath(id)}>{name}</button>)}</div>
  {categories.map(cat=><section key={cat} className="library-group"><h2>{toolCategoryNames[cat]}</h2><div className="library-grid tool-grid">{shown.filter(t=>t.category===cat).sort((a,b)=>Number(a.cost==='paid')-Number(b.cost==='paid')).map(t=><article key={t.id} id={`tool-${t.id}`}><div className="course-card-top"><span className={`tag cost-${t.cost}`}>{costNames[t.cost]}</span>{t.license&&<span className="tag">{t.license}</span>}</div><h3><a href={t.url} target="_blank" rel="noreferrer">{t.name} <Icon name="external"/></a></h3><p>{t.summary}</p><p className="fine"><strong>Best for:</strong> {t.bestFor}</p></article>)}</div></section>)}
  <section className="section-space prose-section"><h2>Using assets responsibly</h2><p>Keep a credits file listing every asset, where it came from, and its license. CC0 assets can be used freely. CC-BY assets need credit to their creator. Some assets and some AI generator plans forbid commercial use or require attribution. Stores such as Steam ask developers to disclose AI-generated content.</p><p className="fine">Tool information last checked: October 2026.</p></section>
 </div>;
}
/** A production checklist of every image and video slot in the foundations courses. Not linked from the main navigation. */
function MediaChecklist(){
 const lessons=useFoundationLessons();
 if(lessons===null)return <div className="page loading">Collecting media slots…</div>;
 const slots=lessons.flatMap(l=>l.blocks.filter((b):b is {type:'media';media:MediaSlotData}=>b.type==='media').map(b=>({lesson:l,media:b.media})));
 const finished=slots.filter(s=>s.media.src).length;
 return <div className="page"><PageTitle eyebrow="Course artwork" title="Media slots" description={`${finished} of ${slots.length} chapter illustrations are ready. Expand an entry to preview the artwork or open its chapter to see it in context.`}/>
  {foundationCourses.map(c=><section key={c.id} className="library-group"><h2>{c.title}</h2>{slots.filter(s=>s.lesson.courseId===c.id).map(({lesson,media})=><details key={media.id} className="disclosure media-row"><summary><span className={`checkpoint ${media.src?'filled':''}`} aria-label={media.src?'Has media':'Needs media'}>{media.src?<Icon name="check"/>:''}</span><code>{media.id}</code><span>{lesson.title}</span></summary><MediaSlot media={media}/><p className="fine">Alt text: {media.alt}</p><Link className="text-link" to={`/courses/${lesson.courseId}/lessons/${lesson.id}`}>Open chapter <Icon name="arrow-right"/></Link></details>)}</section>)}
 </div>;
}

function reviewQuestion(id:string):Question{const concept=conceptById[id];const index=concepts.findIndex(c=>c.id===id);const distractors=[concepts[(index+7)%concepts.length],concepts[(index+13)%concepts.length]];const answer=index%3;const options=distractors.map(c=>c.definition);options.splice(answer,0,concept.definition);return{id:`concept-${id}`,prompt:`Which explanation best describes ${concept.title.toLowerCase()}?`,options,answer,explanation:`${concept.why} For example: ${concept.example}`,concept:id};}
function Review(){const {progress}=useProgress();const [now,setNow]=useState(Date.now());const due=dueConcepts(progress,now);const [current,setCurrent]=useState<string|null>(()=>dueConcepts(progress)[0]||null);const [answered,setAnswered]=useState(false);useEffect(()=>{const timer=setInterval(()=>setNow(Date.now()),30000);return()=>clearInterval(timer);},[]);useEffect(()=>{if(!current&&due.length)setCurrent(due[0]);},[due.join(','),current]);const nextDue=Object.values(progress.review).sort((a,b)=>a.due-b.due)[0];return <div className="page narrow-page"><PageTitle eyebrow="Retrieval practice" title="Make it stick." description="Retrieve the idea before looking it up. A wrong answer is useful information: it brings the concept back sooner."/><div className="review-meta"><span>{due.length} due now</span><span>{Object.keys(progress.review).length} concepts in your queue</span><span>{progress.reviewDays.length} days practiced</span></div>{current?<><QuestionCard key={current} question={reviewQuestion(current)} review onCheck={()=>setAnswered(true)}/>{answered&&<><Link className="text-link" to={`/concepts/${current}`}>Explore this mental model <Icon name="arrow-right"/></Link><div className="button-row section-space"><button className="button" onClick={()=>{setCurrent(dueConcepts(progress)[0]||null);setAnswered(false);setNow(Date.now());}}>Next concept <Icon name="arrow-right"/></button></div></>}</>:<section className="empty-state"><span className="checkpoint large"><Icon name="check"/></span><h2>{Object.keys(progress.review).length?'You’re caught up.':'Your queue starts with a chapter.'}</h2><p>{nextDue?`Next review: ${new Date(nextDue.due).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}.`:'Complete a chapter to add its concepts. Missed practice questions also join the queue.'}</p><Link className="button ghost" to="/learn">Back to learning <Icon name="arrow-right"/></Link></section>}<details className="disclosure section-space"><summary>How review timing works</summary><p>New concepts return after one day. Correct reviews expand to 1, 3, 7, 14, then 30 days. A missed answer returns after five minutes. Dates use this browser’s local time, and progress stays on this device.</p></details></div>;}
function ProgressPage(){const {progress,importData,reset}=useProgress();const [message,setMessage]=useState('');const dialog=useRef<HTMLDialogElement>(null);function download(){const blob=new Blob([JSON.stringify(progress,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download='ez-gamedev-progress.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setMessage('Progress exported. Keep this file to restore it later.');}return <div className="page narrow-page"><PageTitle eyebrow="Device-local progress" title="Your learning, kept close." description="No account needed. Progress belongs to this browser; export a copy before changing devices or clearing browser data."/><div className="progress-stat-row"><div><strong>{progress.completed.length}</strong><span>chapters completed</span></div><div><strong>{availableCourses.filter(c=>{const p=courseProgress(progress,c.id);return p.total>0&&p.done===p.total;}).length}</strong><span>courses completed</span></div><div><strong>{Object.keys(progress.review).length}</strong><span>concepts encountered</span></div></div>{availableCourses.map(c=><section className="section-space" key={c.id}><h3>{c.title}</h3><ProgressBar course={c}/></section>)}<section className="section-space"><h2>Keep a copy</h2><div className="button-row"><button className="button" onClick={download}>Export progress</button><label className="button ghost import-button">Import progress<input type="file" accept=".json,application/json" aria-label="Import progress JSON" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>2_000_000)throw new Error('That file is too large for a progress export.');importData(await file.text());setMessage('Progress imported. This replaces the previous local history.');}catch(error){setMessage(error instanceof Error?error.message:'Could not import this file.');}e.target.value='';}}/></label></div><p className="fine">Import replaces the existing history. Export your current history first if you want to keep both copies.</p><p role="status">{message}</p></section><section className="section-space reset-section"><h2>Start fresh</h2><p>Clear completed chapters, quiz history, project milestones, and review scheduling.</p><button className="button ghost" onClick={()=>dialog.current?.showModal()}>Reset local progress</button></section><dialog ref={dialog} className="reset-dialog"><h2>Reset your progress?</h2><p>This removes the history stored in this browser. Export a copy first if you might need it later.</p><div className="button-row"><button className="button ghost" onClick={()=>dialog.current?.close()}>Keep progress</button><button className="button danger" onClick={()=>{reset();dialog.current?.close();setMessage('Local progress has been reset.');}}>Reset progress</button></div></dialog></div>;}
function Labs(){return <div className="page narrow-page"><PageTitle eyebrow="Play with the model" title="Small experiments. Useful answers." description="These are teaching simulations. Change a value, predict the result, and connect what happens to your game."/>{(['coordinates','loop','velocity','collision','states','parallax','isometric','tree','signals','feel','transforms','camera','raycast','navigation'] as const).map(kind=><Demo key={kind} kind={kind}/>)}</div>;}
function NotFound(){return <div className="page empty-state"><span className="eyebrow">Off the map</span><h1>This checkpoint isn’t here.</h1><p>Return to the course map to choose a valid chapter.</p><Link className="button" to="/courses">Open course map <Icon name="arrow-right"/></Link></div>;}
